{
  "name": "opencode-glm-usage",
  "version": "0.1.4",
  "description": "OpenCode TUI plugin that shows Zhipu (智谱/GLM/Z.ai/BigModel) quota usage — 5h token limit, monthly MCP limit, 24h token total, per-model and per-tool breakdown — in the sidebar.",
  "type": "module",
  "exports": {
    "./tui": "./index.tsx"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "opencode-tui-plugin",
    "zhipu",
    "zhipuai",
    "glm",
    "z.ai",
    "bigmodel",
    "usage",
    "quota",
    "sidebar"
  ],
  "license": "MIT",
  "author": "Zhyolo",
  "repository": {
    "type": "git",
    "url": "https://github.com/Zhyolo/opencode-glm-usage.git"
  },
  "homepage": "https://github.com/Zhyolo/opencode-glm-usage",
  "bugs": {
    "url": "https://github.com/Zhyolo/opencode-glm-usage/issues"
  },
  "dependencies": {
    "solid-js": "1.9.12",
    "@opentui/solid": "0.4.3"
  },
  "peerDependencies": {
    "@opencode-ai/plugin": ">=1.17.0"
  },
  "devDependencies": {
    "@opencode-ai/plugin": "^1.17.13",
    "@opentui/solid": "0.4.3",
    "solid-js": "1.9.12",
    "typescript": "^5.8.2"
  },
  "files": [
    "index.tsx",
    "README.md",
    "LICENSE"
  ],
  "publishConfig": {
    "registry": "https://registry.npmjs.org/",
    "access": "public"
  },
  "engines": {
    "opencode": ">=1.17.0"
  }
}
